  /// The field to use for sorting todos. Valid values: 'created_at',
  /// 'start_date', 'due_date'.
  sort_field String

  /// Sort direction preference. Valid values: 'asc', 'desc'.
  sort_direction String

  /// How to handle null values in sorting. Valid values: 'first', 'last'.
  null_handling String

  /// Indicates if these are the default sorting preferences for the user.
  is_default Boolean

  /// Timestamp when the sorting preferences were created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the sorting preferences were last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the sorting preferences were soft deleted.
